import{_ as r,o as a,c as t,a5 as o}from"./chunks/framework.CXroN2RO.js";const s="/study/images/os/system-calls-and-privilege.svg",m=JSON.parse('{"title":"システムコールでユーザーモードからカーネルモードへ","description":"","frontmatter":{"title":"システムコールでユーザーモードからカーネルモードへ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"Windows x64でWin32 APIからカーネルへ処理が移る経路を追い、CPUの権限移行、引数の検査、待機によるスレッドの切り替えを区別する。","aliases":["システムコール","syscall","system call","ユーザーモード","カーネルモード","user mode","kernel mode","特権レベル","ntdll","NtCreateFile","PreviousMode","SYSRET","トラップ","割り込み","ページフォルト"],"verification":"Microsoft LearnとIntel SDMに照合し、Windows x64のntdll.dll 10.0.26100.9949でNtCreateFileをLLVM 14.0.6により逆アセンブル（2026-11-06）"}},"headers":[],"relativePath":"os/system-calls-and-privilege.md","filePath":"os/system-calls-and-privilege.md"}'),n={name:"os/system-calls-and-privilege.md"};function d(i,e,l,c,h,f){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="システムコールでユーザーモードからカーネルモードへ" tabindex="-1">システムコールでユーザーモードからカーネルモードへ <a class="header-anchor" href="#システムコールでユーザーモードからカーネルモードへ" aria-label="Permalink to &quot;システムコールでユーザーモードからカーネルモードへ&quot;">​</a></h1><p>ゲームが <code>CreateFileW</code> でアセットを開くとき、OSがファイル名を解決し、アクセス権を確認してハンドルを作ります。アプリのコードからOSのサービスを依頼する入口が<strong>システムコール</strong>です。CPUはカーネル用に設定された入口へ移り、呼び出したスレッドの文脈でOSのコードを実行し始めます。処理に待ちが生じると、途中で別のスレッドにCPUを渡すことがあります。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/libraries-and-headers" target="_blank" rel="noreferrer">Microsoftのネイティブシステムサービスの説明</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/context-switches" target="_blank" rel="noreferrer">Windowsのコンテキストスイッチ</a></p><h2 id="cpuの権限と、osが認めるアクセス権" tabindex="-1">CPUの権限と、OSが認めるアクセス権 <a class="header-anchor" href="#cpuの権限と、osが認めるアクセス権" aria-label="Permalink to &quot;CPUの権限と、OSが認めるアクセス権&quot;">​</a></h2><p>通常のWindows x64アプリは<strong>ユーザーモード</strong>で動きます。x64では一般に現在の特権レベルが3です。Windowsカーネルなどのコードは特権レベル0の<strong>カーネルモード</strong>で動きます。CPUは特権命令を使える条件と、メモリのページにアクセスできる条件を検査します。カーネルに処理を渡したあとも、ファイルを開けるか、ハンドルを指定した操作に使えるかは、OSが要求元の権限をもとに判断します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoftのユーザーモードとカーネルモード</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/object-handles" target="_blank" rel="noreferrer">Windowsのオブジェクトハンドル</a></p><p>アプリが持つポインターは、通常、そのプロセス内の仮想アドレスです。ファイルハンドルは、OSに渡す参照用の値です。カーネルは受け取った値を、要求元のアドレス空間やハンドル表、許可されたアクセス権に沿って解釈します。<a href="/study/os/virtual-memory.html">仮想メモリ</a> · <a href="/study/os/windows-handles.html">Windowsのハンドル</a></p><h2 id="win32-apiからx64のカーネル入口へ" tabindex="-1">Win32 APIからx64のカーネル入口へ <a class="header-anchor" href="#win32-apiからx64のカーネル入口へ" aria-label="Permalink to &quot;Win32 APIからx64のカーネル入口へ&quot;">​</a></h2><p>代表的な経路では、<code>CreateFileW</code> を実装するユーザーモードのライブラリが、<code>ntdll.dll</code> の <code>NtCreateFile</code> を使います。Win32側は引数の準備と結果の変換を担います。<code>NtCreateFile</code> は <code>NTSTATUS</code> を返し、成功時に出力先へハンドルを設定します。<code>CreateFileW</code> は失敗時に <code>INVALID_HANDLE_VALUE</code> を返します。Win32の呼び出し回数とカーネルへの移行回数は分けて数えます。APIの実装によっては複数のサービスを呼びます。<code>QueryPerformanceCounter</code> は、使う時刻源によってユーザーモード内で値を取得できます。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/libraries-and-headers" target="_blank" rel="noreferrer">ネイティブサービスの入口</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/ntifs/nf-ntifs-ntcreatefile" target="_blank" rel="noreferrer">NtCreateFileの出力と戻り値</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilew#return-value" target="_blank" rel="noreferrer">CreateFileWの戻り値</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/sysinfo/acquiring-high-resolution-time-stamps#general-faq-about-qpc-and-tsc" target="_blank" rel="noreferrer">QPCとカーネル移行</a></p><p>Windows x64の <code>ntdll.dll</code>（ファイルバージョン <code>10.0.26100.9949</code>）から <code>NtCreateFile</code> の入口を逆アセンブルした例です。次の表示では途中の分岐を省いています。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov r10, rcx   ; SYSCALL が上書きする RCX の値を退避</span></span>
<span class="line"><span>mov eax, 55h   ; この DLL で観測したサービス番号</span></span>
<span class="line"><span>...            ; 入口の経路を選ぶ命令</span></span>
<span class="line"><span>syscall        ; CPU がカーネルの入口へ移る</span></span>
<span class="line"><span>ret            ; 復帰後にユーザーモードの呼び出し元へ戻る</span></span></code></pre></div><p>従来のx64の <code>SYSCALL</code> 経路では、CPUが次の命令のアドレスを <code>RCX</code> に、フラグを <code>R11</code> に保存し、OSが <code>IA32_LSTAR</code> に設定したアドレスへ特権レベル0で移ります。ユーザー側のスタックポインター <code>RSP</code> を記録してカーネル側のスタックへ切り替えることや、サービスを選び実行することはOS側の処理です。観測したサービス番号はそのDLLの実装に属し、Windowsのビルドが変わると変わり得ます。アプリからは公開されたWin32 APIの引数と戻り値を使います。<a href="https://cdrdv2-public.intel.com/774492/325383-sdm-vol-2abcd.pdf" target="_blank" rel="noreferrer">Intel SDM Volume 2のSYSCALL命令</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/libraries-and-headers" target="_blank" rel="noreferrer">MicrosoftのWindowsネイティブ入口の説明</a></p><h2 id="カーネルが受け取った引数を検査する" tabindex="-1">カーネルが受け取った引数を検査する <a class="header-anchor" href="#カーネルが受け取った引数を検査する" aria-label="Permalink to &quot;カーネルが受け取った引数を検査する&quot;">​</a></h2><ul><li><strong>ハンドル</strong>。参照先の種類と、要求された操作に使えるアクセス権を確かめます。たとえば <code>ObReferenceObjectByHandle</code> は、指定された種類やアクセス権の検査を行い、使える場合にカーネル側のオブジェクト参照を取得します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/wdm/nf-wdm-obreferenceobjectbyhandle" target="_blank" rel="noreferrer">MicrosoftのObReferenceObjectByHandle</a></li><li><strong>ポインターと長さ</strong>。ユーザー側から来たバッファについては、アドレスや範囲を検査し、実際に読み書きするときの例外やバッファの寿命も扱います。他のスレッドが検査後に領域の保護を変えることもあります。I/Oの方式に応じ、OSやドライバーはコピー用バッファや、対象ページをロックして参照する方法などを使い分けます。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/previousmode" target="_blank" rel="noreferrer">呼び出し元のモードを保持するPreviousMode</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/wdm/nf-wdm-probeforread" target="_blank" rel="noreferrer">MicrosoftのProbeForRead</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ifs/buffer-handling" target="_blank" rel="noreferrer">WindowsのI/Oバッファ</a></li></ul><h2 id="待機したスレッドはカーネル側から再開する" tabindex="-1">待機したスレッドはカーネル側から再開する <a class="header-anchor" href="#待機したスレッドはカーネル側から再開する" aria-label="Permalink to &quot;待機したスレッドはカーネル側から再開する&quot;">​</a></h2><figure class="study-figure"><img src="`+s+'" alt="すぐ終わる要求では、スレッドAの実行がユーザー、カーネル、ユーザーの順に続く。待機する要求では、Aがカーネルで待ち始め、CPUでBが実行される。完了後にAが選ばれると、Aはカーネル内の続きから再開してユーザーへ戻る。" width="760" height="431" loading="lazy"><figcaption>CPUのモードが変わる箇所と、CPUで走るスレッドが変わる箇所を分けています。<a href="/study/images/os/system-calls-and-privilege.svg" target="_blank" rel="noopener noreferrer">システムコールと待機の図を拡大</a></figcaption></figure><p>短い処理では、呼び出したスレッドがカーネル側の処理を終えてからユーザーモードへ戻れます。同期I/Oなどで結果を待つときは、そのスレッドの文脈が保存され、CPUは別の実行可能なスレッドを走らせられます。要求が完了すると元のスレッドが再び実行可能になり、スケジューラーに選ばれた時点でカーネル側の続きから処理を進めて、ユーザーモードへ戻ります。非同期I/Oでは、要求を出した呼び出しが先に戻り、完了を別に受け取る経路もあります。<a href="/study/os/thread-scheduling.html">スレッドのスケジューリング</a> · <a href="/study/os/file-read-journey.html">ファイル読み取りの経路</a> · <a href="/study/os/asynchronous-file-io.html">非同期ファイルI/O</a></p><h2 id="osに処理が移るきっかけを区別する" tabindex="-1">OSに処理が移るきっかけを区別する <a class="header-anchor" href="#osに処理が移るきっかけを区別する" aria-label="Permalink to &quot;OSに処理が移るきっかけを区別する&quot;">​</a></h2><table tabindex="0"><thead><tr><th>きっかけ</th><th>発生する理由</th><th>OSが受け取るもの</th></tr></thead><tbody><tr><td>システムコール</td><td>スレッドが <code>SYSCALL</code> などの命令でサービスを要求する</td><td>サービスの指定と引数。処理後は呼び出し側の続きへ戻る</td></tr><tr><td>外部割り込み</td><td>デバイスやタイマーなどからCPUに通知が届く</td><td>どの割り込みが届いたか。実行中の命令の結果とは別のタイミングで発生する</td></tr><tr><td>ページフォルト <code>#PF</code></td><td>命令のメモリアクセスで、ページ表から有効な変換と必要な権限を得られない</td><td>問題のアドレスとアクセスの情報。ページの準備などで解決できれば、元の命令を再試行できる</td></tr><tr><td>トラップ型の例外</td><td>例として、デバッガーが置いた <code>INT3</code> をCPUが実行する</td><td>例外の種類と保存した実行状態。<code>INT3</code> の保存先は命令の直後</td></tr></tbody></table><p>Windowsの資料では、カーネルへの移行の説明で「トラップ」という言葉が広く使われることがあります。Intel SDMの<strong>トラップ型の例外</strong>は、保存する命令位置で区別する用語です。OSが <code>#PF</code> を解決できたときは問題が起きた命令を再試行でき、<code>INT3</code> ではデバッガーが保存された次の命令位置をもとに処理します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/previousmode" target="_blank" rel="noreferrer">MicrosoftのPreviousMode</a> · <a href="https://cdrdv2-public.intel.com/825758/253668-sdm-vol-3a.pdf" target="_blank" rel="noreferrer">Intel SDM Volume 3Aの割り込みと例外</a> · <a href="/study/tools/windows/debugger-breakpoints-and-watchpoints.html">Windowsのブレークポイント</a></p>',18)])])}const u=r(n,[["render",d]]);export{m as __pageData,u as default};
